# DISCLAMER: This file is largely generated by AI due to complexity.
"""Compatibility shim for the generalized converter-environment registry.

The implementation moved to :mod:`iSpy.boot.converter_envs` when iSpy gained
separate TFLite and (manual-only) Hailo conversion environments.  This module
keeps the historical RKNN-private names importable, because optimizer tests and
diagnostics patch them directly.  Every wrapper resolves its target dynamically
so ``mock.patch.object(_rknn_converter_env, "_provision", ...)`` continues to
intercept the code that actually runs.
"""

from __future__ import annotations

import hashlib
import json
import logging
import platform
import shutil
import subprocess
import sys
from pathlib import Path

from iSpy.boot import converter_envs as _generic

logger = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Historical constants
# ---------------------------------------------------------------------------

_RKNN_SPEC = _generic.CONVERTER_ENVS["rknn"]
assert _RKNN_SPEC is not None

DEPSET_VERSION = _RKNN_SPEC.depset_version
RKNN_TOOLKIT_VERSION = _RKNN_SPEC.toolkit_version
_RKNN_FULL_BASE = _generic._RKNN_FULL_BASE
_RKNN_FULL_WHEELS = _generic.RKNN_FULL_WHEELS
_CONVERTER_REQUIREMENTS = list(_RKNN_SPEC.requirements)
_VERIFY_SCRIPT = _RKNN_SPEC.verify_script
_LIGHT_VERIFY_SCRIPT = _RKNN_SPEC.light_verify_script
_LIGHT_VERIFY_INTERVAL = _RKNN_SPEC.light_verify_interval
_MIN_FREE_BYTES = _RKNN_SPEC.min_free_bytes
_SPACE_ERRORS = _generic._SPACE_ERRORS
_VENV_CREATE_TIMEOUT = _generic._VENV_CREATE_TIMEOUT
_PIP_INSTALL_TIMEOUT = _generic._PIP_INSTALL_TIMEOUT
_VERIFY_TIMEOUT = _generic._VERIFY_TIMEOUT
_LIGHT_VERIFY_TIMEOUT = _generic._LIGHT_VERIFY_TIMEOUT

ConverterEnvError = _generic.ConverterEnvError


# ---------------------------------------------------------------------------
# Identity / paths
# ---------------------------------------------------------------------------


def _cache_root() -> Path:
    """Return the base cache directory (legacy override still supported)."""
    return _generic._cache_root()


def _arch_key() -> str:
    return _generic._arch_key()


def _python_tag() -> str:
    return _generic._python_tag()


def _identity() -> dict[str, str]:
    """Return the legacy RKNN identity shape.

    Both spellings of the toolkit version are included for callers that still
    inspect ``rknn_toolkit_version``.  Only the canonical keys participate in
    the environment hash/manifest.
    """
    identity = _generic._identity(_RKNN_SPEC)
    identity["rknn_toolkit_version"] = RKNN_TOOLKIT_VERSION
    return identity


def _canonical_identity(identity: dict[str, str]) -> dict[str, str]:
    return {
        "python_tag": identity.get("python_tag", _python_tag()),
        "arch": identity.get("arch", _arch_key()),
        "toolkit_version": identity.get(
            "toolkit_version", identity.get("rknn_toolkit_version", RKNN_TOOLKIT_VERSION)
        ),
        "depset_version": str(identity.get("depset_version", DEPSET_VERSION)),
    }


def _identity_hash(identity: dict[str, str]) -> str:
    return _generic._identity_hash(_canonical_identity(identity))


def _env_dir(identity: dict[str, str]) -> Path:
    return _generic._env_dir(_RKNN_SPEC, _canonical_identity(identity))


def _manifest_path(env_dir: Path) -> Path:
    return _generic._manifest_path(env_dir)


def _is_py(env_dir: Path) -> Path:
    return _generic._is_py(env_dir)


def _lock_path() -> Path:
    return _generic._lock_path(_RKNN_SPEC)


# ---------------------------------------------------------------------------
# Locking / manifest
# ---------------------------------------------------------------------------


def _pid_alive(pid: int) -> bool:
    return _generic._pid_alive(pid)


def _build_lock(lock_path: Path, timeout: float = 600.0):
    return _generic._build_lock(lock_path, timeout=timeout, label="RKNN")


def _read_manifest(env_dir: Path) -> dict | None:
    return _generic._read_manifest(env_dir)


def _env_is_current(env_dir: Path) -> bool:
    if not _is_py(env_dir).exists():
        return False
    manifest = _read_manifest(env_dir)
    if manifest is None:
        return False
    for key, value in _canonical_identity(_identity()).items():
        if manifest.get(key) != value:
            return False
    return True


def _cleanup_orphans(current_hash: str) -> None:
    root = _cache_root() / f"{_RKNN_SPEC.format}_env"
    if not root.is_dir():
        return
    for entry in root.iterdir():
        if not entry.is_dir() or entry.name == current_hash:
            continue
        shutil.rmtree(entry, ignore_errors=True)
        logger.info("Removed stale RKNN converter environment: %s", entry)


# ---------------------------------------------------------------------------
# Provisioning wrappers
# ---------------------------------------------------------------------------


def _pip_failure_message(returncode: int, tail: str) -> str:
    return _generic._pip_failure_message(_RKNN_SPEC, returncode, tail)


def _looks_out_of_space(text: str) -> bool:
    return _generic._looks_out_of_space(text)


def _proc_text(proc) -> str:
    return _generic._proc_text(proc)


def _purge_pip_cache() -> bool:
    return _generic._purge_pip_cache()


def _pip_install(py: Path, *requirements: str, no_deps: bool = False) -> None:
    return _generic._pip_install(
        _RKNN_SPEC,
        py,
        *requirements,
        no_deps=no_deps,
        purge_cache=_purge_pip_cache,
    )


def _verify(py: Path) -> None:
    return _generic._verify(_RKNN_SPEC, py)


def _light_verify(py: Path, env_dir: Path) -> bool:
    return _generic._light_verify(
        _RKNN_SPEC, py, env_dir, interval=_LIGHT_VERIFY_INTERVAL
    )


def _toolkit_wheel_url() -> str:
    key = (_arch_key(), _python_tag())
    filename = _RKNN_FULL_WHEELS.get(key)
    if filename is None:
        supported = sorted(
            f"{a} {v}" for (a, v) in _RKNN_FULL_WHEELS if a == key[0]
        )
        raise ConverterEnvError(
            f"No rknn-toolkit2 {RKNN_TOOLKIT_VERSION} wheel for {key[0]} "
            f"(Python {key[1]}). Supported: {', '.join(supported)}. "
            "RKNN conversion is not possible on this architecture/Python ABI."
        )
    return f"{_RKNN_FULL_BASE}/{filename}"


def _free_bytes(env_dir: Path) -> tuple[int, Path] | None:
    return _generic._free_bytes(env_dir)


def _check_disk_space(env_dir: Path) -> None:
    return _generic._check_disk_space(
        _RKNN_SPEC, env_dir, purge_cache=_purge_pip_cache
    )


def _provision(env_dir: Path) -> Path:
    return _generic._provision(
        _RKNN_SPEC,
        env_dir,
        wheel_url=lambda *_args: _toolkit_wheel_url(),
        pip_install=_pip_install,
        verify=_verify,
        check_disk_space=_check_disk_space,
    )


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------


def ispy_source_root() -> Path:
    return _generic.ispy_source_root()


def converter_python() -> Path:
    """Return the Python executable of a ready RKNN converter environment."""
    identity = _identity()
    env_dir = _env_dir(identity)
    py = _is_py(env_dir)

    if _env_is_current(env_dir):
        if _light_verify(py, env_dir):
            logger.debug("Reusing RKNN converter environment at %s", env_dir)
            _cleanup_orphans(_identity_hash(identity))
            return py
        logger.warning(
            "RKNN converter environment at %s failed light verification - "
            "rebuilding it.",
            env_dir,
        )

    lock_path = _lock_path()
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    with _build_lock(lock_path):
        if _env_is_current(env_dir) and _light_verify(py, env_dir):
            return py
        _cleanup_orphans(_identity_hash(identity))
        from iSpy.core import network_policy

        if network_policy.is_offline():
            raise ConverterEnvError(
                "the RKNN converter environment is not provisioned and "
                "offline mode is on - provisioning it needs pip downloads. "
                "Convert the model on a machine with internet (or copy a "
                "provisioned env over), or turn offline mode off and reboot."
            )
        py = _provision(env_dir)
        _cleanup_orphans(_identity_hash(identity))
        return py


def converter_env_status() -> dict:
    """Return a JSON-serialisable RKNN status dict (legacy shape + extras)."""
    identity = _identity()
    env_dir = _env_dir(identity)
    status = _generic.converter_env_status("rknn")
    # Status is a diagnostic: an unsupported Python/arch must be reported,
    # not crash `ispy env list` or the settings page.
    status.update(
        {
            "env_dir": str(env_dir),
            "env_python": str(_is_py(env_dir)),
            "exists": env_dir.exists(),
            "current": _env_is_current(env_dir),
            "identity": identity,
            "identity_hash": _identity_hash(identity),
            "toolkit_wheel_url": _generic._safe_wheel_url(_RKNN_SPEC),
        }
    )
    return status
